import{z as i,x as B,o as A,c as s,q as e,j as r,D as E,d as n,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"深宽比与刻蚀负荷","description":"","frontmatter":{"title":"深宽比与刻蚀负荷","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/etch-loading-ar.md","filePath":"litho/etch-loading-ar.md","lastUpdated":1791063341000}'),p={name:"litho/etch-loading-ar.md"};function d(m,a,h,D,R,c){const t=B("Mermaid");return A(),s("div",null,[a[2]||(a[2]=e('<h1 id="深宽比与刻蚀负荷" tabindex="-1">深宽比与刻蚀负荷 <a class="header-anchor" href="#深宽比与刻蚀负荷" aria-label="Permalink to &quot;深宽比与刻蚀负荷&quot;">​</a></h1><div class="epigraph"><p>同一套离子与自由基，开口一深、邻近一密，到达底部的通量就不是晶圆平均值；速率随几何走，叫深宽比相关刻蚀，也叫负荷。</p><footer>—— 刻蚀通称：ARDE 与宏 / 微负荷，不把某一腔体的速率表当成自然常数</footer></div><p><a href="/litho/rie-pattern-transfer">上一课</a>把 RIE 写成协同与硬掩模转印，默认开口够宽、通量够均匀。缺口是几何：接触孔、浅槽和密线之间，深宽比（AR）和开口面积一变，中性基与离子到达底部的概率变，CD 与深度不再跟紧凑偏置走。本课钉 ARDE 与负荷效应。孔阵列相对线空为什么更难印、更难刻，留给<a href="/litho/contact-hole-patterning">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的选择比窗口是对「某种膜、某种偏置」说的。同样食谱，孤立宽槽先到底，密线或深孔还在爬——这是深宽比相关刻蚀（ARDE）：高 AR 特征速率下降。晶圆上开放面积大，自由基被吃光，全局速率下降，叫宏负荷；局部密度高，邻近图形抢通量，叫微负荷。OPC 若只用一个与密度无关的偏置，疏密交界会先出窗口。</p><p><span class="marginnote">直觉类比：宏负荷像全城只开一家餐厅，客流（开放面积）越大每桌出菜越慢；微负荷像邻桌拼到同一个服务员，密区图形互相抢通量，隔壁空区没人管、反而刻得快。所以「刻蚀速率」没有全局平均值，只有随邻域变化的值。</span></p><p>缺口不是再讲离子从哪来，而是：转印函数对<strong>布局</strong>敏感。DTCO 的密度规则、虚拟图形（dummy）和填充，有一部分是在买更均匀的刻蚀通量，而不是在买光学对比。</p><h3 id="arde-不是焦深" tabindex="-1">ARDE 不是焦深 <a class="header-anchor" href="#arde-不是焦深" aria-label="Permalink to &quot;ARDE 不是焦深&quot;">​</a></h3><p>光学焦深按 \\(\\lambda/\\mathrm{NA}^2\\) 变薄，是空中像沿轴。ARDE 是腔体传输：中性基要扩散进孔，离子有角分散，深孔底部通量掉。两者都会让「看起来一样的设计 CD」在硅上分叉，计量链不同。把深孔刻不穿写成曝光不足，会去拧剂量。</p><p><span class="marginnote">数字实例：深宽比就是深度除以宽度。直径 \\(50\\,\\mathrm{nm}\\)、深 \\(500\\,\\mathrm{nm}\\) 的接触孔 \\(\\mathrm{AR}=10\\)；同样深度的 \\(200\\,\\mathrm{nm}\\) 宽槽只有 \\(\\mathrm{AR}=2.5\\)。一份食谱要同时伺候这两类形状，选择比窗口就被最慢的 \\(\\mathrm{AR}=10\\) 钉死。</span></p><p><span class="marginnote">过刻用来照顾最慢的孔，同时最宽的槽已经在啃硬掩模或衬底。窗口是最慢特征与最快特征之间的选择比，不是平均速率。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上把图形分成 AR 族与开口面积族，用截面和终点信号看谁先停、谁还在走。缓解不外乎：降 AR（先开硬掩模再换化学）、加钝化抑制宽槽横向、用脉冲或低占空比改离子/中性比、布局上插 dummy 把局部开放面积拉平。ALE 用循环把「每圈去掉的量」从通量梯度里解开，那是薄膜课的工具；本课的连续 RIE 仍活在通量里。</p><p>虚拟图形必须同时过光学与刻蚀两关：dummy 会改空中像邻近，也会改微负荷。只为刻蚀填满、不管 OPC，邻近热点会换一个地方出现。</p>',14)),(A(),r(o,null,{default:E(()=>[l(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20AR%5B%22%E9%AB%98%E6%B7%B1%E5%AE%BD%E6%AF%94%22%5D%20--%3E%20ARDE%5B%22%E5%BA%95%E9%83%A8%E9%80%9A%E9%87%8F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20MAC%5B%22%E5%A4%A7%E5%BC%80%E6%94%BE%E9%9D%A2%E7%A7%AF%22%5D%20--%3E%20LOAD%5B%22%E5%AE%8F%E8%B4%9F%E8%8D%B7%3A%20%E8%87%AA%E7%94%B1%E5%9F%BA%E8%80%97%E5%B0%BD%22%5D%0A%20%20MIC%5B%22%E5%B1%80%E9%83%A8%E5%AF%86%E5%8C%BA%22%5D%20--%3E%20MICRO%5B%22%E5%BE%AE%E8%B4%9F%E8%8D%B7%3A%20%E9%82%BB%E5%8C%BA%E6%8A%A2%E9%80%9A%E9%87%8F%22%5D%0A%20%20ARDE%20--%3E%20OC%5B%22%E8%BF%87%E5%88%BB%E7%85%A7%E9%A1%BE%E6%9C%80%E6%85%A2%E5%AD%94%22%5D%0A%20%20LOAD%20--%3E%20OC%0A%20%20MICRO%20--%3E%20CD%5B%22%E7%96%8F%E5%AF%86%20CD%20%E5%88%86%E5%8F%89%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="填充图形是刻蚀的-ret" tabindex="-1">填充图形是刻蚀的 RET <a class="header-anchor" href="#填充图形是刻蚀的-ret" aria-label="Permalink to &quot;填充图形是刻蚀的 RET&quot;">​</a></h3><p>光学有 SRAF；刻蚀有密度填充。两者都改变邻域算子。区别是：SRAF 不应在晶圆上作为独立图形留下；dummy 往往留下，要能被后续 CMP 或电学接受。规则手册里的「最小/最大密度」常是负荷约束，被误写成分辨率约束。</p><p><span class="marginnote">常见误区：dummy 不是免费精度。它在改微负荷的同时也改了光学邻近，只为密度填满、不重跑 OPC，热点只是换个地方冒出来。把密度规则当分辨率规则去拧照明，方向本来就错了。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中性自由基无方向，运输靠扩散；孔越深越窄，口部消耗后底部欠饱和，速率掉——ARDE 的化学支。离子有鞘层加速，但仍有角分布；深孔壁挡住斜离子，底部离子通量也掉，物理支同样 ARDE。宏负荷是整片开放面积的反应器级质量守恒：面积大，自由基分母变大。微负荷是图案尺度的局部耗尽。三者可以同时在，不能用一个「loading 百分比」打天下。</p><p>这解释了接触孔过刻比线空更凶：孔的 AR 更高、底部更黑，终点要以孔为准，线槽就过刻。也解释了为何紧凑刻蚀模型至少要一个密度项；没有这一项，上一课的全芯片核在 SRAM 与逻辑交界处系统性地偏。</p>',6)),(A(),r(o,null,{default:E(()=>[l(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20LINE%5B%22%E7%BA%BF%E6%A7%BD%EF%BC%9AAR%20%E8%BE%83%E4%BD%8E%22%5D%20--%3E%20LB%5B%22%E5%BA%95%E9%83%A8%E9%80%9A%E9%87%8F%E5%B0%9A%E5%8F%AF%22%5D%0A%20%20HOLE%5B%22%E6%8E%A5%E8%A7%A6%E5%AD%94%EF%BC%9AAR%20%E6%9B%B4%E9%AB%98%22%5D%20--%3E%20HB%5B%22%E5%BA%95%E9%83%A8%E9%80%9A%E9%87%8F%E6%8E%89%E5%BE%97%E5%BF%AB%22%5D%0A%20%20LB%20--%3E%20EP%5B%22%E7%BB%88%E7%82%B9%E6%A3%80%E6%B5%8B%E4%BB%A5%E6%9C%80%E6%85%A2%E7%89%B9%E5%BE%81%E5%8D%B3%E5%AD%94%E4%B8%BA%E5%87%86%22%5D%0A%20%20HB%20--%3E%20EP%0A%20%20EP%20--%3E%20OE%5B%22%E7%BA%BF%E6%A7%BD%E7%BB%A7%E7%BB%AD%E8%A2%AB%E8%BF%87%E5%88%BB%22%5D%0A%20%20OE%20--%3E%20RISK%5B%22%E5%95%83%E7%A1%AC%E6%8E%A9%E6%A8%A1%E6%88%96%E8%A1%AC%E5%BA%95%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">常见误区：终点信号是全晶圆的平均，深孔「还没到底」在信号上只是尾巴变长。拿平均终点决定过刻，等于让所有快特征陪最慢特征受罚；监控 AR 分层速率比只盯终点时间更能提前发现窗口收窄。</span></p><p><span class="marginnote">同一食谱换掩模开口率，速率可以明显变。比较两台刻蚀机的「快慢」而不声明开口率和 AR，没有意义。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要发明某国产刻蚀机在某一 AR 下的纳米/分。通称机制够用：通量随几何变。不要把 ARDE 写成只有深硅 MEMS 才有——逻辑接触孔和金属沟槽已经在这个词里。本课不重写 Coburn 协同，只把它放进有限深宽比的腔。</p><p>CMP 碟形、电镀填充也会随密度变，那是后道另一条负荷，不要和干法微负荷混成一张图。下一课的孔图形化会把光学低对比和本课的高 AR 叠在同一类图形上。</p><p><span class="marginnote">出处：半导体刻蚀通称中的 ARDE、macro/micro loading；与 RIE 教材中的传输限制。不引用未公开的腔体速率曲线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ARDE：高深宽比降低底部离子/自由基通量，速率下降。</li><li>宏负荷吃整片开口面积；微负荷吃局部密度。</li><li>过刻窗口夹在最慢孔与最快槽之间。</li><li>dummy 与密度规则有一部分是刻蚀 RET，不是光学 \\(k_1\\)。</li><li>接触孔图形化下一课，光学与刻蚀在孔上会合。</li><li>出处：刻蚀通称 ARDE 与负荷；不编造工具速率。</li></ul>',8))])}const C=i(p,[["render",d]]);export{u as __pageData,C as default};
